const isThinkingEnabled = override?.thinkingEnabled ?? settings?.globalThinkingEnabled ?? false;

const handleBudgetChange = (value: number) => {
  if (!settings || !onUpdateSettings) return;
  const newOverrides = { ...settings.modelOverrides };
